INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e6900001-0001-4001-8001-000000000001', 'TUT-ELEKTRONIK13-001', 'b4444444-4444-4444-4444-444444444444', $$Potensiometer: Atur Volume dan Cahaya$$, 'potensiometer-atur-volume-dan-cahaya', $$Panduan lengkap memahami dan merangkai potensiometer sebagai pengatur volume dan kecerahan lampu, dari teori pembagi tegangan sampai praktik aman.$$, 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Kontrol yang Hanya Bisa Hidup atau Mati$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kamu ingin mengatur kecerahan lampu atau volume speaker secara halus, tetapi yang tersedia hanya saklar on-off. Hasilnya: lampu terlalu terang atau terlalu redup, suara terlalu keras atau terlalu pelan, tidak ada titik tengah yang pas. Potensiometer menyelesaikan masalah ini dengan memberikan kontrol putar yang mulus dari nol sampai maksimal.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Potensiometer Adalah Resistor yang Bisa Diatur$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Potensiometer adalah resistor variabel dengan tiga kaki. Dua kaki di ujung adalah ujung-ujung resistor tetap (misalnya 10 kilo-ohm), sedangkan kaki tengah yang disebut wiper bergerak mengikuti putaran kenop. Saat kenop diputar, posisi wiper berubah sehingga tegangan yang diteruskan ke beban ikut berubah. Inilah prinsip pembagi tegangan yang menjadi dasar semua kontrol volume dan dimmer sederhana.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Potensiometer 10k ohm linier (kode B10K) — 1 buah$$, $$LED + resistor 220 ohm — 1 set$$, $$Breadboard dan kabel jumper$$, $$Baterai 9 volt + konektor, atau papan Arduino$$, $$Multimeter untuk memeriksa nilai resistansi$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah Merangkai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$1. Kenali tiga kaki potensiometer: dua kaki luar adalah ujung resistor tetap, kaki tengah adalah wiper.$$, $$2. Hubungkan satu kaki luar ke kutub positif baterai dan kaki luar satunya ke kutub negatif (ground).$$, $$3. Hubungkan kaki tengah (wiper) ke kaki anoda LED melalui resistor 220 ohm, lalu katoda LED ke ground.$$, $$4. Putar kenop perlahan dari ujung ke ujung dan amati kecerahan LED berubah secara halus.$$, $$5. Ukur tegangan di kaki tengah dengan multimeter sambil memutar kenop untuk melihat pembagi tegangan bekerja.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko yang Perlu Diwaspadai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan menghubungkan potensiometer langsung ke listrik PLN 220 volt — komponen ini hanya untuk rangkaian tegangan rendah (di bawah 24 volt). Memutar kenop terlalu cepat saat terhubung ke beban sensitif bisa menimbulkan lonjakan arus. Selalu matikan sumber daya sebelum mengubah rangkaian, dan pastikan nilai potensiometer sesuai kebutuhan (10k untuk sinyal, bukan untuk beban besar seperti motor).$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Rangkaian berhasil jika: (1) LED menyala redup di satu ujung putaran dan terang di ujung satunya, (2) perubahan kecerahan terasa mulus tanpa kedip, (3) multimeter menunjukkan tegangan 0 sampai mendekati tegangan baterai di kaki tengah. Jika LED tidak menyala sama sekali, periksa polaritas LED dan pastikan kaki tengah yang dipakai adalah wiper, bukan kaki luar. Tindak lanjut: coba ganti LED dengan buzzer untuk membuat kontrol volume nada, atau sambungkan kaki tengah ke pin analog Arduino (A0) untuk membaca posisi kenop sebagai angka 0-1023.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e6900002-0002-4002-8002-000000000002', 'TUT-MASAK18-001', 'b7777777-7777-7777-7777-777777777777', $$Ikan Bakar: Bumbu Meresap$$, 'ikan-bakar-bumbu-meresap', $$Resep dan teknik membakar ikan agar bumbu meresap sampai ke daging: pemilihan ikan, bumbu oles, teknik bakar, dan trik anti gosong.$$, 'id', 7, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ikan Bakar Hambar di Dalam, Gosong di Luar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Keluhan paling umum saat membakar ikan: bagian luar sudah hitam gosong tetapi daging di dalam masih hambar dan anyir. Penyebabnya biasanya bumbu hanya dioles di permukaan sesaat sebelum dibakar, api terlalu besar, dan ikan tidak dikerat. Dengan teknik yang benar, bumbu bisa meresap sampai ke tulang dan ikan matang merata tanpa gosong.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Kunci Bumbu Meresap Ada Tiga$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Pertama, keratan: sayat daging ikan 2-3 cm dalamnya di kedua sisi agar bumbu masuk ke serat daging. Kedua, marinasi: diamkan ikan berbumbu minimal 30 menit (lebih lama lebih baik) di kulkas. Ketiga, bumbu oles ganda: olesan pertama sebelum dibakar untuk rasa, olesan kedua saat dibakar untuk karamelisasi dan aroma. Tiga hal ini yang membedakan ikan bakar warung terkenal dengan yang biasa saja.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Bahan dan Bumbu$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Ikan segar 500 gram (nila, gurame, atau kembung), bersihkan dan kerat$$, $$Bumbu halus: 5 bawang merah, 3 bawang putih, 3 cabai merah, 1 ruas kunyit, 1 ruas jahe, 1 sdt ketumbar$$, $$2 sdm kecap manis, 1 sdm minyak goreng, 1 sdt garam, 1/2 sdt gula$$, $$Bumbu oles: sisa bumbu halus + 2 sdm kecap manis + 1 sdm margarin leleh$$, $$Pelengkap: lalapan, sambal kecap, dan jeruk nipis$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah-langkah Memasak$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$1. Lumuri ikan dengan air jeruk nipis dan garam, diamkan 10 menit untuk mengurangi anyir, lalu bilas.$$, $$2. Balurkan bumbu halus ke seluruh ikan termasuk ke dalam keratan, diamkan 30-60 menit di kulkas.$$, $$3. Panaskan bara api atau grill sampai sedang (bukan api besar menyala-nyala).$$, $$4. Bakar ikan 5-7 menit per sisi sambil dioles bumbu oles setiap 2-3 menit.$$, $$5. Balik cukup 2 kali agar daging tidak hancur; total waktu bakar sekitar 12-15 menit.$$, $$6. Angkat saat daging mudah terlepas dari tulang dan olesan terakhir masih mengilap.$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Api terlalu besar membuat kulit gosong sebelum daging matang — gunakan bara, bukan lidah api. Terlalu sering membolak-balik membuat ikan hancur. Jangan membakar ikan yang masih beku karena bagian dalam tidak akan matang merata. Hati-hati asap: bakar di tempat berventilasi baik dan jauhkan anak kecil dari area panggangan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Ikan bakar berhasil jika: (1) warna luar cokelat keemasan merata, tidak hitam gosong, (2) daging mudah terlepas dari tulang saat dicungkil garpu, (3) rasa bumbu terasa sampai daging bagian dalam, bukan hanya di kulit, (4) aroma bakaran harum tanpa bau anyir. Sajikan segera dengan sambal kecap dan lalapan selagi hangat. Tindak lanjut: sisa bumbu oles bisa disimpan di kulkas 3 hari untuk bakaran berikutnya; coba variasi ikan bakar bumbu rujak atau parape khas Makassar, dan teknik yang sama bisa dipakai untuk ayam bakar dengan waktu marinasi lebih lama.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e6900003-0003-4003-8003-000000000003', 'EXP-KIMIA21-001', 'c4444444-4444-4444-4444-444444444444', $$Tembaga: Logam Konduktor$$, 'tembaga-logam-konduktor', $$Mengenal tembaga: sifat kimia dan fisika, mengapa menjadi konduktor listrik terbaik kedua, serta perannya dalam peradaban manusia.$$, 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Logam Kemerahan yang Menghubungkan Dunia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setiap kali kamu menyalakan lampu atau mengisi daya ponsel, kemungkinan besar arus listrik itu mengalir melalui kabel tembaga. Tembaga (simbol Cu, dari bahasa Latin cuprum) adalah salah satu logam pertama yang digunakan manusia — sudah dikenal sejak 9000 tahun lalu — dan hingga kini tetap tak tergantikan sebagai penghantar listrik.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Sifat-sifat Tembaga$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Tembaga murni berwarna kemerahan mengilap, lunak, dan mudah dibentuk (ditempa menjadi kawat tipis atau lempeng). Titik leburnya 1085 derajat Celsius. Yang paling istimewa: tembaga adalah konduktor listrik terbaik kedua setelah perak, dan konduktor panas yang sangat baik. Ia juga tahan korosi karena membentuk lapisan oksida pelindung berwarna hijau kebiruan yang disebut patina — itulah warna atap-atap gedung tua di Eropa.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Mengapa Tembaga Menghantar Listrik dengan Hebat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Rahasianya ada pada struktur atomnya. Setiap atom tembaga menyumbang satu elektron bebas yang bisa bergerak leluasa di antara atom-atomnya, seperti lautan elektron. Ketika diberi beda potensial (tegangan), elektron-elektron ini mengalir serentak membentuk arus listrik. Perak sebenarnya sedikit lebih baik, tetapi tembaga jauh lebih murah dan melimpah, sehingga menjadi pilihan praktis untuk seluruh infrastruktur listrik dunia.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Tembaga dalam Kehidupan Sehari-hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Kabel listrik rumah, gedung, dan jaringan PLN$$, $$Lilitan motor listrik, dinamo, dan transformator$$, $$Papan sirkuit (PCB) pada semua perangkat elektronik$$, $$Pipa air dan atap bangunan karena tahan korosi$$, $$Uang logam dan perhiasan (dicampur logam lain)$$, $$Alat masak tembaga yang menghantar panas merata$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tembaga dan Tubuh Manusia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Tembaga juga unsur penting bagi tubuh dalam jumlah kecil: membantu pembentukan sel darah merah, menjaga kesehatan saraf, dan memperkuat daya tahan tubuh. Kekurangan tembaga bisa menyebabkan anemia. Namun dalam jumlah besar tembaga bersifat racun — itulah sebabnya air dari pipa tembaga yang terlalu lama menggenang sebaiknya dibuang dulu sebelum diminum.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e6900004-0004-4004-8004-000000000004', 'EXP-SEJARAH19-001', 'c8888888-8888-8888-8888-888888888888', $$Pemberontakan DI/TII$$, 'pemberontakan-di-tii', $$Latar belakang, jalannya, dan berakhirnya pemberontakan Darul Islam/Tentara Islam Indonesia (1948-1962) dalam bingkai sejarah nasional.$$, 'id', 7, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Pemberontakan Terlama dalam Sejarah Indonesia Merdeka$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$DI/TII (Darul Islam/Tentara Islam Indonesia) adalah gerakan pemberontakan bersenjata yang berlangsung dari 1948 hingga 1962 — sekitar 14 tahun — di beberapa wilayah Indonesia. Dipimpin oleh Sekarmadji Maridjan Kartosoewirjo di Jawa Barat, gerakan ini kemudian menyebar ke Aceh, Sulawesi Selatan, dan Kalimantan Selatan dengan tokoh-tokoh lokalnya masing-masing.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Latar Belakang: Kekecewaan Pasca-Perjanjian Renville$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Akar persoalan bermula dari Perjanjian Renville (Januari 1948) antara Indonesia dan Belanda. Salah satu isinya mewajibkan pasukan TNI di Jawa Barat (daerah kantong) hijrah ke Jawa Tengah. Kartosoewirjo yang saat itu memimpin laskar di Jawa Barat menolak hijrah dan memilih bertahan. Ketegangan memuncak setelah penangkapan para pemimpin dan kekecewaan terhadap arah politik pemerintah pusat.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Proklamasi Negara Islam Indonesia$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Pada 7 Agustus 1949, Kartosoewirjo memproklamasikan berdirinya Negara Islam Indonesia (NII) di Desa Cisampah, Tasikmalaya, Jawa Barat. Proklamasi ini menolak bentuk Negara Kesatuan Republik Indonesia dan menawarkan negara berdasarkan syariat Islam. Sejak itu pasukannya yang menamakan diri Tentara Islam Indonesia melakukan perlawanan bersenjata terhadap TNI.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Penyebaran ke Daerah Lain$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Gerakan serupa muncul di beberapa daerah dengan motif yang beragam, dari kekecewaan politik hingga tuntutan otonomi. Di Aceh dipimpin Daud Beureueh (1953), di Sulawesi Selatan oleh Kahar Muzakkar (1952), dan di Kalimantan Selatan oleh Ibnu Hajar. Pemerintah pusat menghadapi pemberontakan di banyak front secara bersamaan, sehingga penyelesaiannya memakan waktu belasan tahun.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Berakhirnya Pemberontakan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Satu per satu pemberontakan daerah padam melalui operasi militer dan pendekatan damai: Daud Beureueh menyerah pada 1959, Kahar Muzakkar tewas pada 1965. Puncaknya, Kartosoewirjo ditangkap pada Juni 1962 di Gunung Geber, Tasikmalaya, lalu dijatuhi hukuman mati. Dengan tertangkapnya Kartosoewirjo, pemberontakan DI/TII di Jawa Barat — yang menjadi pusat gerakan — resmi berakhir.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e6900005-0005-4005-8005-000000000005', 'SCH-SMA-SOS5-001', 'd5555555-5555-5555-5555-555555555555', $$Sosiologi Kelas 11: Lembaga Sosial$$, 'sosiologi-kelas-11-lembaga-sosial', $$Materi sosiologi kelas 11 tentang lembaga sosial: pengertian, ciri-ciri, jenis-jenis, fungsi, dan contoh dalam kehidupan sehari-hari, lengkap dengan latihan soal.$$, 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Menjelaskan pengertian lembaga sosial menurut para ahli$$, $$Mengidentifikasi ciri-ciri lembaga sosial$$, $$Menyebutkan jenis-jenis lembaga sosial beserta contohnya$$, $$Menganalisis fungsi lembaga sosial dalam masyarakat$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Lembaga Sosial$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Lembaga sosial (social institution) adalah sistem norma dan nilai yang mengatur pola perilaku anggota masyarakat untuk memenuhi kebutuhan hidupnya. Menurut Soerjono Soekanto, lembaga sosial adalah himpunan norma yang mengatur tindakan individu dalam memenuhi kebutuhan pokoknya. Sederhananya: jika interaksi sosial adalah hubungan antarorang, maka lembaga sosial adalah aturan mainnya yang sudah melembaga dan diakui bersama.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Ciri-ciri Lembaga Sosial$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Memiliki tujuan yang jelas, misalnya lembaga pendidikan bertujuan mencerdaskan$$, $$Memiliki norma dan tata tertib yang mengatur anggotanya$$, $$Memiliki alat kelengkapan seperti pengurus, gedung, dan simbol$$, $$Bersifat kekal — keberadaannya tidak bergantung pada individu tertentu$$, $$Memiliki sanksi bagi yang melanggar normanya$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Jenis-jenis Lembaga Sosial$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Berdasarkan fungsinya, lembaga sosial dibagi menjadi lima: (1) Lembaga keluarga — mengatur perkawinan, keturunan, dan sosialisasi anak. (2) Lembaga pendidikan — mengatur pewarisan ilmu dan keterampilan, contohnya sekolah dan universitas. (3) Lembaga ekonomi — mengatur produksi dan distribusi kebutuhan, contohnya pasar dan koperasi. (4) Lembaga politik — mengatur kekuasaan dan ketertiban, contohnya pemerintah dan partai politik. (5) Lembaga agama — mengatur hubungan manusia dengan Tuhan, contohnya masjid, gereja, dan pura.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh dalam Kehidupan Sehari-hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Ketika kamu berangkat ke sekolah, kamu sedang berinteraksi dengan lembaga pendidikan. Saat ibumu berbelanja di pasar, ia berinteraksi dengan lembaga ekonomi. Saat keluargamu mengadakan musyawarah, itu adalah lembaga keluarga yang bekerja. Bahkan saat mengikuti pemilu, kamu sedang menjalankan fungsi lembaga politik. Semua lembaga ini saling terkait membentuk keteraturan sosial.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Soal 1: Jelaskan perbedaan antara interaksi sosial dan lembaga sosial! Kunci: interaksi adalah hubungan antarindividu/kelompok, sedangkan lembaga adalah sistem norma yang mengatur pola hubungan tersebut.$$, $$Soal 2: Sebutkan 3 ciri lembaga sosial beserta contohnya! Kunci: memiliki tujuan (sekolah mencerdaskan), memiliki norma (tata tertib sekolah), memiliki sanksi (hukuman bagi pelanggar).$$, $$Soal 3: Termasuk lembaga apa sajakah kegiatan gotong royong membersihkan kampung? Kunci: lembaga sosial kemasyarakatan / lembaga politik tingkat lokal karena mengatur ketertiban dan kerja sama warga.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by) VALUES ('e6900006-0006-4006-8006-000000000006', 'SCH-SD-IPS14-001', 'd3333333-3333-3333-3333-333333333333', $$IPS Kelas 5: Kenampakan Alam$$, 'ips-kelas-5-kenampakan-alam', $$Materi IPS kelas 5 tentang kenampakan alam: dataran rendah, dataran tinggi, pantai, gunung, dan pemanfaatannya, lengkap dengan latihan soal.$$, 'id', 6, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'MEMBER', true, 'DRAFT', 'DEVELOPED_BY', 1, false, 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 1, jsonb_build_object('items', ARRAY[$$Menyebutkan macam-macam kenampakan alam di Indonesia$$, $$Menjelaskan ciri-ciri setiap kenampakan alam$$, $$Menyebutkan pemanfaatan kenampakan alam bagi manusia$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Kenampakan Alam?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Kenampakan alam adalah segala sesuatu yang ada di permukaan bumi dan terbentuk secara alami, bukan buatan manusia. Indonesia yang sangat luas memiliki kenampakan alam yang lengkap: ada dataran rendah, dataran tinggi, pantai, gunung, lembah, danau, dan sungai. Setiap kenampakan alam punya ciri khas dan dimanfaatkan manusia dengan cara berbeda.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Dataran Rendah dan Dataran Tinggi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Dataran rendah adalah wilayah datar dengan ketinggian 0-200 meter di atas permukaan laut, misalnya pesisir utara Jawa. Tanahnya subur sehingga cocok untuk sawah, perkebunan, dan permukiman. Dataran tinggi adalah wilayah datar di ketinggian lebih dari 200 meter, misalnya Dataran Tinggi Dieng. Udaranya sejuk sehingga cocok untuk kebun teh, kopi, dan sayuran.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Pantai dan Laut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Pantai adalah batas antara daratan dan lautan. Indonesia punya garis pantai terpanjang kedua di dunia! Pantai dimanfaatkan untuk pelabuhan, perikanan, tambak garam, dan pariwisata. Laut di sekitarnya kaya ikan, mutiara, dan minyak bumi. Anak-anak pesisir biasanya akrab dengan perahu nelayan dan pasar ikan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Gunung dan Pegunungan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Gunung adalah tonjolan besar di permukaan bumi, misalnya Gunung Semeru dan Gunung Rinjani. Gunung berapi menghasilkan tanah vulkanik yang sangat subur, sehingga lerengnya banyak dijadikan kebun. Selain itu gunung menyimpan air sebagai sumber sungai, dan menjadi tempat wisata pendakian. Namun kita harus waspada karena gunung berapi bisa meletus.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal dan Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Soal 1: Sebutkan 4 kenampakan alam yang ada di Indonesia! Kunci: dataran rendah, dataran tinggi, pantai, gunung (boleh juga danau, sungai, lembah).$$, $$Soal 2: Mengapa dataran rendah cocok untuk persawahan? Kunci: tanahnya datar dan subur, air mudah didapat, cocok untuk tanaman padi.$$, $$Soal 3: Apa manfaat gunung berapi bagi manusia? Kunci: tanah vulkanik subur untuk pertanian, sumber air, objek wisata, dan pasir bahan bangunan.$$]::text[]));
